const path = require('path');
process.chdir(path.join(__dirname, '..'));

require('./src/config/db');
const fs = require('fs');
const antiBan = require('./src/services/antiBan');
const { AccessUsers } = require('./src/models');

const delays = new Set();
for (let i = 0; i < 30; i++) delays.add(antiBan.nextVariableDelayMs());
const arr = [...delays];
console.log('jitter unique', arr.length, 'min', Math.min(...arr), 'max', Math.max(...arr));
console.log('inRange', Math.min(...arr) >= 4000 && Math.max(...arr) <= 20000);
console.log('hours', antiBan.isWithinWorkingHours());

const phone = '9561888002';
const code = 'CORE' + Date.now().toString(36).toUpperCase().slice(-5);
for (const u of AccessUsers.list()) {
  if (String(u.phone).includes('9561888002') || u.name === 'Core Rewrite') {
    try {
      AccessUsers.remove(u.id);
    } catch (_) {}
  }
}
const u = AccessUsers.create({ name: 'Core Rewrite', phone, access_code: code });
console.log('created', u.status);
console.log('unauth', !AccessUsers.findByPhone('9990001111'));
console.log('wrong', AccessUsers.tryUnlock('+91' + phone, 'NOPE1234'));
console.log('unlock', AccessUsers.tryUnlock('+91 ' + phone, code));
console.log('after', AccessUsers.displayStatus(AccessUsers.findByPhone('91' + phone)));
AccessUsers.remove(u.id);

const s = fs.readFileSync('src/services/whatsapp.js', 'utf8');
const block = s.slice(
  s.indexOf('async handleIncomingMessage'),
  s.indexOf('async handleChatBridge')
);
const bad = [...block.matchAll(/workflowEngine|Drawflow|ChatFlow|getActiveGraph|isHardcodedGreeting/g)].map(
  (m) => m[0]
);
console.log('inbound bad', bad.length ? bad : 'NONE');
console.log('deskForward', s.includes('deskForward'));
console.log('no bindEngine', !s.includes('bindEngine'));

require('./src/services/whatsapp');
require('./src/services/deskForward');
require('./src/services/workflowEngine');
console.log('modules load OK');
